changeSet.sql:
CREATE TABLE note_sentence (
    note_id              INTEGER      NOT NULL REFERENCES note(note_id) ON DELETE CASCADE,
    sentence_id          VARCHAR(100) NOT NULL,
    position             TEXT         NOT NULL DEFAULT 'a0',
    origin_sentence_id   VARCHAR(100),
    origin_migration_id  INTEGER      REFERENCES migration(migration_id) ON DELETE SET NULL,
    origin_commit_hash   VARCHAR(40),
    sentence_id_history  JSONB        NOT NULL DEFAULT '[]'::jsonb,
    migration_confidence NUMERIC(3,2),
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by           VARCHAR(255),
    CONSTRAINT pk_note_sentence PRIMARY KEY (note_id, sentence_id)
);
CREATE INDEX idx_note_sentence_sentence ON note_sentence(sentence_id);
CREATE INDEX idx_note_sentence_position ON note_sentence(sentence_id, position);

CREATE TABLE note_scratchpad (
    note_id       INTEGER     NOT NULL REFERENCES note(note_id) ON DELETE CASCADE,
    scratchpad_id INTEGER     NOT NULL REFERENCES scratchpad(scratchpad_id) ON DELETE CASCADE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    removed_at    TIMESTAMPTZ,
    CONSTRAINT pk_note_scratchpad PRIMARY KEY (note_id, scratchpad_id)
);
CREATE INDEX idx_note_scratchpad_live ON note_scratchpad(scratchpad_id) WHERE removed_at IS NULL;
